schema_ddl:
CREATE TABLE corrieri (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE CHECK (LENGTH(partita_iva) = 11)
);

CREATE TABLE veicoli (
    id SERIAL PRIMARY KEY,
    targa TEXT NOT NULL UNIQUE,
    tipo TEXT,
    corriere_id INT NOT NULL REFERENCES corrieri(id)
);

CREATE TABLE spedizioni (
    id SERIAL PRIMARY KEY,
    data_spedizione DATE NOT NULL,
    destinazione TEXT NOT NULL,
    peso NUMERIC(10,2) CHECK (peso >= 0),
    veicolo_id INT NOT NULL REFERENCES veicoli(id)
);
